# 第二批新空间：建职业探索空间，建完接着扩成完整一天（串行，避免限流）
cd /Users/aisandbox/Documents/companydata
mk() { echo "== 建空间 $1"; id=$(npx tsx scripts/lab-create-space.mts "$1" 2>&1 | tee -a scripts/.create-batch2.log | grep -o '[0-9a-f]\{8\}-[0-9a-f]\{4\}-[0-9a-f]\{4\}-[0-9a-f]\{4\}-[0-9a-f]\{12\}' | tail -1); echo "   id=$id"; echo "$1 $id" >> scripts/.create-batch2.ids
  [ -n "$id" ] && { echo "== 完整一天 $1"; npx tsx scripts/lab-build-full-day.mts "${id:0:8}" --hint "$2" 2>&1 | tail -3; }; }
mk "数字芯片设计工程师" "芯片设计公司数字前端 / 验证工程师的一天：晨会领任务、读设计规格、在时序报告里找违例路径并改约束、写 testbench 跑仿真在波形里定位 bug、代码评审、回归结果分析、给后端出交接说明。每章都要有可操作的虚拟工位（桌面型：代码 / 波形 / 时序报告 / 约束），带教的是资深验证工程师。"
mk "机械设计工程师（CAD 制图）" "机械设计工程师在设计部的一天：晨会接改图任务、读三视图补缺失尺寸、基准与公差标注、装配干涉检查、与工艺和采购沟通、出图审查签字。每章都要有可操作的虚拟工位（CAD 画布：标注、修改、检查），带教的是设计室主任。"
mk "应急管理指挥调度员" "应急管理局指挥中心值班调度员遇到山洪预警的一天：接到气象预警、研判受威胁村庄、下达转移指令、调度消防与救援队伍、资源紧缺时的取舍、信息不全时的决策与留痕、灾后复盘。每章都要有可操作的虚拟工位（沙盘地图 + 事件流 + 决策记录），带教的是指挥中心值班长。"
mk "变电站运维值班员" "变电站运维值班员的一天：交接班与设备巡视、接到调度倒闸操作票、操作前核对与模拟预演、验电挂接地线的顺序、带电区域安全距离、异常信号处置、操作后记录。每章都要有可操作的虚拟工位（顺序类操作，错一步即违规），带教的是老值班长。"
mk "转炉炼钢工" "钢厂转炉炼钢工的一天：班前会与炉况交接、装铁水废钢、吹炼与氧枪控制、测温取样、出钢时机判断、合金化与脱氧、炉后复盘。每章都要有可操作的虚拟工位（温度 / 成分 / 氧枪位 / 炉渣都是传感器点位），带教的是炼钢班长。"
mk "沥青路面摊铺施工员" "沥青路面摊铺施工员在公路施工现场的一天：班前交底与天气窗口判断、运料车到场测温、摊铺机速度与厚度控制、压路机碾压遍数与温度窗口、接缝处理、压实度检测与记录。每章都要有可操作的虚拟工位（温度 / 压实度 / 轨迹都是数采点位），带教的是摊铺班组长。"
echo "== 批次完成"
